 async function uploadFiles(e:React.FormEvent<HTMLFormElement>){
  e.preventDefault();const form=e.currentTarget,f=new FormData(form),investmentId=selected,category=String(f.get('upload_category')||'faktury'),publish=f.get('upload_publish')==='on';
  const files=f.getAll('upload_files').filter((v):v is File=>v instanceof File&&Boolean(v.name));
  await run(async()=>{
   if(!investmentId)throw Error('Wybierz inwestycję.');
   if(installer&&category!=='zdjecia')throw Error('Konto wykonawcy może dodawać tylko zdjęcia instalacji.');
   if(!files.length||files.length>MAX_UPLOAD_FILES)throw Error('Wybierz od 1 do 50 plików.');
   let saved=0,booked=0,review=0,duplicates=0;const failures:string[]=[];
   for(let index=0;index<files.length;index++){
    const file=files[index];setMessage(`Przesyłanie ${index+1} z ${files.length}: ${file.name}`);
    try{
     const {mime,extension}=await inspectUpload(file,category),path=`${investmentId}/${crypto.randomUUID()}.${extension}`;
     const {error:uploadError}=await db.storage.from(UPLOAD_BUCKET).upload(path,file,{contentType:mime,cacheControl:'0',upsert:false});
     if(uploadError)throw uploadError;
     const {data:document,error:saveError}=await db.from('documents').insert({investment_id:investmentId,title:(installer?String(f.get('installation_type')||'Instalacja')+' — ':'')+file.name,category,drive_file_id:null,storage_path:path,mime_type:mime,published:installer||publish,uploaded_by:user.id}).select('id').single();
     if(saveError){const {error:cleanupError}=await db.storage.from(UPLOAD_BUCKET).remove([path]);if(cleanupError)throw Error('Nie zapisano dokumentu; przesłany plik wymaga usunięcia przez administratora.');throw saveError}
     saved++;
     if(['faktury','platnosci'].includes(category)&&document){
      try{setMessage(`Odczyt i księgowanie ${index+1}/${files.length}: ${file.name}`);const status=await readAndBook(document.id,new Blob([file],{type:mime}),category);if(status==='booked')booked++;else if(status==='duplicate')duplicates++;else review++}
      catch(error){review++;await db.from('documents').update({accounting_note:error instanceof Error?error.message:'Sprawdź dane dokumentu ręcznie.',auto_book:false}).eq('id',document.id)}
     }
    }catch(error){failures.push(`${file.name}: ${error instanceof Error?error.message:'Nie udało się przesłać pliku.'}`)}
   }
   await refresh();if(!failures.length)form.reset();
   setMessage(`Dodano ${saved} z ${files.length} plików. ${publish?(['faktury','platnosci','inne'].includes(category)&&inv?.client_invoices_visible!==true?'Opublikowane, ale faktury są ukryte w ustawieniach klienta.':'Udostępnione klientowi.'):'Zapisane jako szkice — klient ich jeszcze nie widzi.'}`+(['faktury','platnosci'].includes(category)?` Zaksięgowano: ${booked}. Do sprawdzenia: ${review}. Duplikaty: ${duplicates}.`:'')+(failures.length?' Nie przesłano: '+failures.join('; '):' Możesz je sprawdzić i udostępnić klientowi.'));
  });
 }
