 async function chargeDuplicate(d:Row){
  if(!financeAdmin)return;
  if(!window.confirm('Ponownie odjąć '+money(d.gross_amount)+' z salda inwestycji „'+(inv?.name||'')+'” za fakturę '+(d.invoice_number||d.title)+'? To świadome doliczenie faktury oznaczonej jako duplikat.'))return;
  await run(async()=>{
   const {data,error}=await db.rpc('charge_duplicate_invoice',{p_document_id:d.id,p_investment_id:selected,p_expected_amount:d.gross_amount});
   if(error)throw Error(error.code==='40001'?'Kwota faktury zmieniła się. Odśwież dane i sprawdź ją ponownie.':error.message);
   try{await refresh()}catch{setMessage('Zapisano obciążenie duplikatu, ale widoku nie udało się odświeżyć. Odśwież stronę.');return}
   setMessage(data?.charged?'Doliczono duplikat — odjęto '+money(data.amount)+' z salda inwestycji.':'Ta kopia faktury została już doliczona. Nie odjęto kwoty ponownie.');
  });
 }
